"use client";
// @zeus-internal
import { motion, useInView, useReducedMotion } from "motion/react";
import { useRef, type ReactNode } from "react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { NumberTicker } from "./03-impact-dashboard/number-ticker";
const REVEAL_VIEWPORT = { once: true, margin: "0px 0px -60px 0px" } as const;
const REVEAL_DURATION = 0.65;
const REVEAL_STAGGER = 0.08;
function useRevealProps(index: number) {
    const reduce = useReducedMotion();
    return {
        initial: { opacity: 0, y: 20 },
        whileInView: reduce ? undefined : { opacity: 1, y: 0 },
        viewport: REVEAL_VIEWPORT,
        transition: { duration: REVEAL_DURATION, delay: index * REVEAL_STAGGER, ease: ARTEMIS_EASE_OUT },
    };
}
function RevealArticle({ index, className, children }: {
    index: number;
    className: string;
    children: ReactNode;
}) {
    const reveal = useRevealProps(index);
    return (<motion.article className={className} {...reveal}>
      {children}
    </motion.article>);
}
function ProgressCard() {
    const reveal = useRevealProps(1);
    const reduce = useReducedMotion();
    const ref = useRef<HTMLElement>(null);
    const inView = useInView(ref, REVEAL_VIEWPORT);
    return (<motion.article ref={ref} aria-label="Progress deployed" aria-valuemax={100} aria-valuemin={0} aria-valuenow={72} role="progressbar" className="art:relative art:min-h-64 art:overflow-hidden art:rounded-3xl art:bg-background art:p-6 art:@min-[640px]/artemis:col-span-2 art:@min-[640px]/artemis:p-8" {...reveal}>
      <div aria-hidden="true" className="art:absolute art:inset-y-0 art:left-0 art:overflow-hidden" style={{ width: "88%" }}>
        <motion.div className="art:absolute art:inset-0 art:origin-left art:bg-linear-to-r art:from-primary/25 art:via-primary/10 art:to-transparent" initial={{ scaleX: 0 }} animate={{ scaleX: inView ? 1 : 0 }} transition={reduce ? { duration: 0 } : { duration: 1.25, delay: 0.12, ease: ARTEMIS_EASE_OUT }}/>
      </div>
      <div className="art:relative art:z-10 art:flex art:items-start art:justify-between art:gap-6">
        <h3 className="art:font-medium art:text-xl">{"Progress deployed"}</h3>
        <span className="art:text-muted-foreground art:text-sm">{"2030 target"}</span>
      </div>
      <p className="art:relative art:z-10 art:mt-12 art:font-medium art:text-5xl art:tabular-nums art:tracking-tight">
        <NumberTicker text="72%"/>
      </p>
    </motion.article>);
}
export default function StatsImpactDashboard() {
