            </motion.div>
            <div className="art:grid art:gap-4 art:@min-[640px]/artemis:grid-cols-2">
              <ProgressCard />
              <RevealArticle index={2} className="art:rounded-3xl art:bg-background art:p-6 art:@min-[640px]/artemis:p-8">
                <span className="art:flex art:size-10 art:items-center art:justify-center art:rounded-full art:bg-background art:text-foreground">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-leaf art:size-5" aria-hidden="true">
                    <path d="M11 20A7 7 0 0 1 9.8 6.1C15.5 5 17 4.48 19 2c1 2 2 4.18 2 8 0 5.5-4.78 10-10 10Z"/>
