                <h3 className="art:mt-8 art:font-medium art:text-xl">{"Local partners"}</h3>
                <p className="art:mt-5 art:font-medium art:text-4xl art:tabular-nums art:tracking-tight">
                  <NumberTicker text="180+"/>
                </p>
                <p className="art:mt-2 art:text-muted-foreground art:text-xs art:uppercase art:tracking-[0.14em]">{"Across 28 regions"}</p>
